/**
 * @summary Send a one-time registration or sign-in code by email
 */
export const sendRegistrationCodeBodyEmailMax = 254;


export const sendRegistrationCodeBodyEmailRegExp = new RegExp('^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$');


export const SendRegistrationCodeBody = zod.object({
  "email": zod.string().max(sendRegistrationCodeBodyEmailMax).regex(sendRegistrationCodeBodyEmailRegExp),
  "role": zod.enum(['cliente', 'administrador_negocio', 'repartidor', 'administrador_sistema'])
})

export const SendRegistrationCodeResponse = zod.object({
  "sent": zod.boolean()
})


/**
 * @summary Confirm a one-time registration or sign-in code
 */
export const confirmRegistrationCodeBodyEmailMax = 254;


export const confirmRegistrationCodeBodyEmailRegExp = new RegExp('^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$');
export const confirmRegistrationCodeBodyCodeRegExp = new RegExp('^[0-9]{6}$');


export const ConfirmRegistrationCodeBody = zod.object({
  "email": zod.string().max(confirmRegistrationCodeBodyEmailMax).regex(confirmRegistrationCodeBodyEmailRegExp),
  "role": zod.enum(['cliente', 'administrador_negocio', 'repartidor', 'administrador_sistema']),
  "code": zod.string().regex(confirmRegistrationCodeBodyCodeRegExp)
})

export const ConfirmRegistrationCodeResponse = zod.object({
  "verified": zod.boolean()
})


/**
 * @summary List pending business administrator registration requests
 */
export const listBusinessAdminRegistrationRequestsResponseEmailRegExp = new RegExp('^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$');


export const ListBusinessAdminRegistrationRequestsResponseItem = zod.object({
  "id": zod.number(),
  "name": zod.string(),
  "email": zod.string().regex(listBusinessAdminRegistrationRequestsResponseEmailRegExp),
  "createdAt": zod.coerce.date()
})
export const ListBusinessAdminRegistrationRequestsResponse = zod.array(ListBusinessAdminRegistrationRequestsResponseItem)


/**
 * @summary Approve or reject a business administrator registration request
 */



export const DecideBusinessAdminRegistrationRequestParams = zod.object({
  "userId": zod.coerce.number().min(1)
})

export const DecideBusinessAdminRegistrationRequestBody = zod.object({
  "decision": zod.enum(['approve', 'reject'])
})

export const DecideBusinessAdminRegistrationRequestResponse = zod.object({
  "decision": zod.enum(['approved', 'rejected'])
})


